<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref } from "vue";
import { useRouter } from "vue-router";
import { Plus, ArrowRight, FolderGit2, RefreshCw, ScanLine } from "lucide-vue-next";
import { api } from "../api";
import type { Dashboard, Project, ScanTask } from "../types";
import PageHeader from "../components/PageHeader.vue";
import Button from "../components/ui/Button.vue";
import StatusBadge from "../components/StatusBadge.vue";
import Loading from "../components/ui/Loading.vue";
import { relativeTime, absoluteTime, durationBetween } from "../utils/time";
const router=useRouter();
const data=ref<Dashboard|null>(null), projects=ref<Project[]>([]), scans=ref<ScanTask[]>([]);
const refreshing=ref(false);
const loading=ref(true), error=ref(""), refreshed=ref("");let timer:number|undefined;let disposed=false;let inFlight=false;
async function load(manual=false):Promise<void>{
 if(manual)refreshing.value=true;
 if(inFlight)return;inFlight=true;
 try{const [d,p,s]=await Promise.all([api.dashboard(),api.listProjects(),api.listScans()]);if(disposed)return;data.value=d;projects.value=p;scans.value=s;error.value="";refreshed.value=new Date().toISOString();}
 catch(e){if(!disposed)error.value=(e as Error).message;}finally{if(!disposed){loading.value=false;refreshing.value=false;}inFlight=false;}
}
const active=computed(()=>scans.value.filter(s=>['pending','claimed','scanning','cancel_requested'].includes(s.status)));
const queue=computed(()=>[...active.value,...scans.value.filter(s=>!active.value.includes(s)).sort((a,b)=>b.id-a.id)].slice(0,3));
const recentProjects=computed(()=>projects.value.slice().sort((a,b)=>b.id-a.id).slice(0,5));
const levels=[{key:'critical',label:'Critical'},{key:'high',label:'High'},{key:'medium',label:'Medium'},{key:'low',label:'Low'},{key:'info',label:'Info'}] as const;
const total=computed(()=>levels.reduce((n,l)=>n+(data.value?.stats[l.key]||0),0));
function scanFor(p:Project):ScanTask|undefined{return scans.value.filter(s=>s.projectId===p.id).sort((a,b)=>b.id-a.id)[0];}
function activity(s:ScanTask):string{try{const p=JSON.parse(s.progressJson||'{}');return p.activity||p.phase||s.currentStage||'';}catch{return s.currentStage||'';}}
function progress(s:ScanTask):number|null{try{const p=JSON.parse(s.progressJson||'{}');if(p.filesTotal>0&&p.progressSource==='verified_coverage'&&typeof p.filesCompleted==='number'&&p.filesCompleted>0)return Math.min(100,Math.round(p.filesCompleted/p.filesTotal*100));}catch{}return null;}
function openScan(s:ScanTask):void{void router.push({name:'scan-detail',params:{id:s.id}});}
onMounted(()=>{void load();timer=window.setInterval(()=>{if(!document.hidden)void load();},10000);});onUnmounted(()=>{disposed=true;if(timer)clearInterval(timer);});
</script>
<template>
 <div class="dashboard">
  <PageHeader title="安全工作台" description="关注正在执行的任务，以及需要研判的风险。"><Button variant="ghost" size="icon" :loading="loading||refreshing" aria-label="刷新工作台" title="刷新工作台" @click="load(true)"><RefreshCw :size="14"/></Button><Button @click="router.push({name:'new-scan'})"><Plus :size="14"/>新建扫描</Button></PageHeader>
  <div v-if="error" class="request-error" role="alert"><span>工作台数据加载失败：{{error}}</span><Button variant="outline" size="sm" @click="load(true)">重试</Button></div>
  <Loading v-if="loading&&!data" text="正在加载工作台…"/>
  <template v-if="data">
   <div class="summary-strip"><div><span>未修复漏洞</span><strong>{{data.stats.openFindings}}</strong><small>按当前扫描结果统计</small></div><div><span>Critical 待处理</span><strong :class="{'risk-number':data.stats.criticalOpen>0}">{{data.stats.criticalOpen}}</strong><small>优先检查与验证</small></div><div><span>扫描执行中</span><strong>{{data.stats.running}}</strong><small>正在执行的任务</small></div><div><span>累计扫描</span><strong>{{data.stats.scans}}</strong><small>{{data.stats.projects}} 个审计项目</small></div></div>
   <div class="dashboard-grid"><div class="dashboard-main">
    <section class="pane queue"><header class="section-head"><h2>扫描队列 <small>{{active.length}} 个正在执行</small></h2><router-link class="section-link" to="/scans">全部扫描 <ArrowRight :size="13"/></router-link></header>
     <article v-for="s in queue" :key="s.id" class="queue-row"><div class="queue-title"><span><FolderGit2 :size="15"/><button @click="openScan(s)">{{s.projectName||s.scanNo}}</button><StatusBadge :status="s.status"/></span><span class="mono scan-no">{{s.scanNo}}</span></div><div class="queue-meta"><span>{{s.scanMode==='quick'?'快速扫描':s.scanMode==='deep'?'深度扫描':'标准扫描'}}</span><span class="model-name" :title="s.model">{{s.model||'未指定模型'}}</span><span :title="absoluteTime(s.createdAt)">{{relativeTime(s.createdAt)}}</span></div><template v-if="active.includes(s)"><div v-if="progress(s)!==null" class="progress-track" role="progressbar" aria-label="已处理文件进度" :aria-valuenow="progress(s)??0" aria-valuemin="0" aria-valuemax="100"><i :style="{width:progress(s)+'%'}"/></div><p class="current-activity">{{activity(s)||'等待扫描器输出执行状态…'}}</p></template><div v-else class="queue-foot"><span>{{s.findingCount}} 项发现 <span class="dot-sep">·</span> 耗时 {{durationBetween(s.startedAt,s.finishedAt)}}</span><Button variant="link" size="sm" @click="openScan(s)">检查发现 <ArrowRight :size="13"/></Button></div><p v-if="s.errorMessage" class="scan-error">{{s.errorMessage}}</p></article>
     <div v-if="!queue.length" class="empty-state"><p class="empty-title">还没有扫描任务</p><p class="empty-hint">上传代码快照后，即可开始第一次安全审计。</p><Button variant="link" size="sm" @click="router.push('/scans/new')">新建扫描</Button></div>
    </section>
    <section class="pane projects-pane"><header class="section-head"><h2>审计项目</h2><router-link class="section-link" to="/projects">全部项目 <ArrowRight :size="13"/></router-link></header><div class="table-scroll"><table v-if="recentProjects.length" class="project-table"><thead><tr><th>项目</th><th>代码快照</th><th>最近扫描</th><th></th></tr></thead><tbody><tr v-for="p in recentProjects" :key="p.id"><td><router-link :to="'/projects/'+p.id" class="project-name"><span class="project-symbol"><FolderGit2 :size="15"/></span><span>{{p.name}}<small>{{p.scanCount}} 次扫描</small></span></router-link></td><td>{{p.snapshotCount}}</td><td><StatusBadge v-if="scanFor(p)" :status="scanFor(p)!.status"/><span v-else class="muted">尚未扫描</span></td><td><Button variant="ghost" size="iconSm" :aria-label="'查看项目 '+p.name" @click="router.push('/projects/'+p.id)"><ArrowRight :size="13"/></Button></td></tr></tbody></table><div v-else class="empty-state"><p class="empty-title">还没有项目</p><router-link class="section-link" to="/projects">创建项目，组织代码资产</router-link></div></div></section>
   </div><aside class="dashboard-aside"><section class="pane"><header class="section-head"><h2>发现的风险</h2><small>{{total}} 项发现</small></header><div class="risk-section"><p class="section-hint">按扫描结果严重度分布</p><div v-if="total" class="severity-bar" aria-hidden="true"><i v-for="l in levels" :key="l.key" :style="{flex:data.stats[l.key],background:'var(--severity-'+l.key+')'}"/></div><router-link v-for="l in levels" :key="l.key" :to="{path:'/findings',query:{severity:l.key}}" class="risk-row"><span><i :style="{background:'var(--severity-'+l.key+')'}"/>{{l.label}}</span><span class="mono">{{data.stats[l.key]}}</span></router-link></div><div class="risk-section risk-action"><ScanLine :size="16"/><h3>从发现到证据</h3><p>检查漏洞的代码位置、分析依据和验证状态，再记录研判结论。</p><router-link class="section-link" to="/findings">进入漏洞列表 <ArrowRight :size="13"/></router-link></div></section><section class="pane engine-pane"><header class="section-head"><h2>最近使用的引擎</h2></header><div v-if="data.engine" class="risk-section"><span class="engine-provider">{{data.engine.provider}}</span><p class="engine-model">{{data.engine.model}}</p><dl><dt>累计扫描</dt><dd>{{data.engine.scanCount}} 次</dd><dt>最近耗时</dt><dd>{{Math.round(data.engine.durationSec)}} 秒</dd></dl><router-link class="section-link" to="/settings/model-configs">管理模型配置 <ArrowRight :size="13"/></router-link></div><div v-else class="empty-state"><p class="empty-hint">完成扫描后显示引擎信息。</p><router-link class="section-link" to="/settings/model-configs">配置模型</router-link></div></section></aside></div><footer class="updated-at">最近更新 {{absoluteTime(refreshed)}} <span>数据来自当前工作空间</span></footer>
  </template>
 </div>
</template>
<style scoped>
.summary-strip{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));padding-bottom:var(--space-6);margin-bottom:var(--space-6);border-bottom:1px solid var(--border-default)}.summary-strip>div{padding:0 var(--space-6);border-right:1px solid var(--border-default)}.summary-strip>div:first-child{padding-left:0}.summary-strip>div:last-child{border:0}.summary-strip span{display:block;font-size:var(--font-size-xs);color:var(--text-secondary)}.summary-strip strong{display:inline-block;font-size:var(--font-size-display);font-weight:500;letter-spacing:-.025em;margin-top:var(--space-3);font-variant-numeric:tabular-nums}.summary-strip small{font-size:var(--font-size-2xs);margin-left:var(--space-3);color:var(--text-tertiary)}.risk-number{color:var(--severity-critical)}.dashboard-grid{display:grid;grid-template-columns:minmax(0,1fr) 285px;gap:var(--space-6)}.dashboard-main,.dashboard-aside{min-width:0}.pane{border-radius:var(--radius-lg);overflow:hidden}.section-head{padding:var(--space-4) var(--space-5);display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid var(--border-default);gap:var(--space-3)}h2{font-size:var(--font-size-md);font-weight:600;margin:0}h2 small{font-size:var(--font-size-xs);font-weight:400;color:var(--text-tertiary);margin-left:var(--space-2)}.section-head>small{font-size:var(--font-size-2xs);color:var(--text-tertiary)}.section-link{display:inline-flex;align-items:center;gap:var(--space-2);font-size:var(--font-size-xs);color:var(--text-secondary)}.section-link:hover{color:var(--accent-primary)}.queue-row{padding:var(--space-5);border-bottom:1px solid var(--border-subtle)}.queue-row:last-child{border:0}.queue-title{display:flex;align-items:center;justify-content:space-between;gap:var(--space-3)}.queue-title>span:first-child{display:flex;align-items:center;gap:var(--space-2);min-width:0;flex-wrap:wrap}.queue-title button{font-size:var(--font-size-sm);font-weight:500;text-align:left;overflow-wrap:anywhere}.queue-title button:hover{color:var(--accent-primary)}.queue-title svg{color:var(--text-tertiary)}.scan-no{font-size:var(--font-size-2xs);color:var(--text-tertiary);flex-shrink:0}.queue-meta{display:flex;gap:var(--space-3);font-size:var(--font-size-xs);color:var(--text-tertiary);margin-top:var(--space-3);flex-wrap:wrap}.model-name{overflow-wrap:anywhere}.queue-foot{display:flex;justify-content:space-between;align-items:center;margin-top:var(--space-3);font-size:var(--font-size-xs);color:var(--text-secondary);gap:var(--space-3)}.dot-sep{margin:0 var(--space-2);color:var(--text-disabled)}.progress-track{height:3px;background:var(--surface-tertiary);margin-top:var(--space-4)}.progress-track i{display:block;height:100%;background:var(--accent-primary)}.current-activity{font-size:var(--font-size-xs);color:var(--text-secondary);margin:var(--space-3) 0 0;overflow-wrap:anywhere}.scan-error{font-size:var(--font-size-xs);color:var(--state-danger);overflow-wrap:anywhere}.projects-pane,.engine-pane{margin-top:var(--space-6)}.table-scroll{overflow:auto}.project-table{width:100%;border-collapse:collapse;text-align:left;white-space:nowrap}.project-table th{font-size:var(--font-size-2xs);font-weight:400;color:var(--text-tertiary);background:var(--surface-secondary);padding:var(--space-2-5) var(--space-5)}.project-table td{padding:var(--space-4) var(--space-5);border-top:1px solid var(--border-subtle);font-size:var(--font-size-xs)}.project-name{display:flex;align-items:center;gap:var(--space-3)}.project-name small{display:block;color:var(--text-tertiary);font-size:var(--font-size-2xs);margin-top:var(--space-1)}.project-symbol{display:grid;place-items:center;width:28px;height:30px;background:var(--surface-secondary);border:1px solid var(--border-default);border-radius:var(--radius-sm);color:var(--text-tertiary)}.risk-section{padding:var(--space-5)}.section-hint{font-size:var(--font-size-xs);color:var(--text-tertiary);margin:0}.severity-bar{height:4px;display:flex;gap:2px;margin:var(--space-4) 0 var(--space-2)}.risk-row{display:flex;justify-content:space-between;font-size:var(--font-size-xs);padding:var(--space-2-5) 0;color:var(--text-secondary)}.risk-row:hover{color:var(--accent-primary)}.risk-row>span:first-child{display:flex;align-items:center;gap:var(--space-2)}.risk-row i{width:5px;height:5px;border-radius:50%}.risk-action{border-top:1px solid var(--border-default)}.risk-action>svg{color:var(--text-tertiary)}h3{font-size:var(--font-size-sm);margin:var(--space-2) 0;font-weight:500}.risk-action p{font-size:var(--font-size-xs);line-height:1.8;color:var(--text-tertiary);margin-bottom:var(--space-4)}.engine-provider{font-size:var(--font-size-xs);color:var(--text-tertiary)}.engine-model{font-size:var(--font-size-sm);font-weight:500;overflow-wrap:anywhere;line-height:1.7;margin:var(--space-2) 0}dl{display:grid;grid-template-columns:1fr auto;font-size:var(--font-size-xs);gap:var(--space-3);margin:var(--space-5) 0;color:var(--text-secondary)}dd{margin:0}.updated-at{display:flex;justify-content:space-between;margin-top:var(--space-6);font-size:var(--font-size-2xs);color:var(--text-tertiary)}
@media(max-width:1200px){.dashboard-grid{grid-template-columns:1fr}.dashboard-aside{display:grid;grid-template-columns:1fr 1fr;gap:var(--space-6)}.engine-pane{margin:0}.summary-strip small{display:none}}
@media(max-width:760px){.summary-strip{grid-template-columns:1fr 1fr;row-gap:var(--space-5)}.summary-strip>div{padding:0 var(--space-4)}.summary-strip>div:nth-child(odd){padding-left:0}.summary-strip>div:nth-child(even){border:0}.dashboard-aside{display:block}.engine-pane{margin-top:var(--space-5)}.queue-title{flex-wrap:wrap}.queue-row{padding:var(--space-4)}.queue-foot{flex-wrap:wrap}.updated-at span{display:none}.section-head{padding:var(--space-4)}h2 small{display:none}}
</style>
